document.addEventListener("DOMContentLoaded", function () {
if (window.__algoliaLanguageSwitcherInitialized) return;
window.__algoliaLanguageSwitcherInitialized = true;

var languageSwitchers = Array.prototype.slice.call(
document.querySelectorAll("[data-language-switcher='true']")
);
if (!languageSwitchers.length) return;

function isInTopNav(node) {
return !!node.closest(".header__top-nav ul, .header__top-nav.mobile ul");
}

function hasAuthoredLanguageList(node) {
return (node.getAttribute("data-authored-language-list") || "").toLowerCase() === "true";
}

function getPreferredLanguageSwitcher(nodes) {
for (var p = 0; p < nodes.length; p++) {
if (isInTopNav(nodes[p]) && hasAuthoredLanguageList(nodes[p])) return nodes[p];
}
for (var i = 0; i < nodes.length; i++) {
if (isInTopNav(nodes[i])) return nodes[i];
}
for (var j = 0; j < nodes.length; j++) {
if (hasAuthoredLanguageList(nodes[j])) return nodes[j];
}
return nodes[0];
}

var languageSwitcher = getPreferredLanguageSwitcher(languageSwitchers);
if (!languageSwitcher) return;

for (var s = 0; s < languageSwitchers.length; s++) {
if (languageSwitchers[s] !== languageSwitcher) {
languageSwitchers[s].remove();
}
}

var languageList = languageSwitcher.querySelector(".languageList");
var languageDropButton = languageSwitcher.querySelector(".dropdown-toggle");

function normalizeLanguageCode(code) {
return (code || "").toString().trim().toLowerCase().replace(/_/g, "-");
}

